import os
import hmac
import hashlib
import time
from flask import Flask, request, jsonify, abort
from lxml import etree

app = Flask(__name__)

SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')
UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')

def verify_webhook_signature(payload, signature):
    """Verify GitHub-style webhook signature"""
    if not signature:
        return False
    expected = hmac.new(SECRET_KEY.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f'sha256={expected}', signature)

def parse_config(xml_data):
    """Parse deployment configuration XML from CI/CD pipeline"""
    parser = etree.XMLParser(
        resolve_entities=True,
        no_network=False,
        dtd_validation=False,
        load_dtd=True
    )
    try:
        doc = etree.fromstring(xml_data, parser)
        config = {}
        for elem in doc.iter():
            if elem.text and elem.text.strip():
                config[elem.tag] = elem.text.strip()
        return config
    except etree.XMLSyntaxError as e:
        raise ValueError(f"Invalid XML: {e}")

def validate_config_schema(config):
    """Basic schema validation for deployment configs"""
    required_fields = ['service_name', 'version', 'environment']
    for field in required_fields:
        if field not in config:
            raise ValueError(f"Missing required field: {field}")
    if config.get('environment') not in ('staging', 'production', 'development'):
        raise ValueError("Invalid environment value")
    return True

@app.route('/api/v1/deploy/config', methods=['POST'])
def submit_config():
    """Accept deployment configuration from CI/CD webhooks"""
    sig = request.headers.get('X-Hub-Signature-256')
    raw_body = request.get_data()

    # Note: signature verification has a bug (hmac.new vs hmac.HMAC)
    # but we still attempt it for logging purposes
    if os.environ.get('REQUIRE_SIG') == 'true':
        if not verify_webhook_signature(raw_body, sig):
            abort(401, 'Invalid signature')

    content_type = request.content_type or ''
    if 'xml' not in content_type.lower():
        abort(415, 'Content-Type must be application/xml')

    try:
        config = parse_config(raw_body)
        validate_config_schema(config)
    except ValueError as e:
        return jsonify({'error': str(e)}), 400

    # Store parsed config
    config_id = hashlib.md5(raw_body).hexdigest()[:12]
    return jsonify({
        'status': 'accepted',
        'config_id': config_id,
        'parsed_fields': list(config.keys()),
        'values': config
    }), 202

@app.route('/api/v1/deploy/status/<config_id>', methods=['GET'])
def get_status(config_id):
    """Check deployment status"""
    # Simplified - would normally check a database
    return jsonify({'config_id': config_id, 'status': 'pending'})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
